import { Fragment } from "react";
import {
  Body,
  Head as EmailHead,
  Html,
  Preview,
  Link,
  Section,
  Row,
  Column,
  Text,
  Img,
  Tailwind,
} from "react-email";

import { DefaultFonts } from "@/components/email/font-default";
import { createEmailTailwindConfig } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type HeaderWithUserDetailsAlignment = "left" | "right";

export type HeaderWithUserDetailsAvatar = "initials" | "image";

export interface HeaderWithUserDetailsProps {
  theme?: EmailTheme;
  logoSrc?: string;
  logoAlt?: string;
  logoHref?: string;
  userName?: string;
  userEmail?: string;
  initials?: string;
  avatarSrc?: string;
  avatarAlt?: string;
  avatar?: HeaderWithUserDetailsAvatar;
  alignment?: HeaderWithUserDetailsAlignment;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  avatarBackgroundColor?: string;
  headingColor?: string;
  textColor?: string;
  mutedTextColor?: string;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const sharedDefaults = {
  avatarAlt: "",
  avatarBackgroundColor: "#f3f4f6",
  backgroundColor: "#fffffe",
  headingColor: "#030712",
  initials: "JD",
  logoAlt: "Maizzle",
  logoHref: "https://example.com",
  logoSrc: emailAsset("maizzle-insignia.png"),
  mutedTextColor: "#6b7280",
  pageBackgroundColor: "#f1f5f9",
  textColor: "#4b5563",
};

type SectionProps = Omit<HeaderWithUserDetailsProps, "theme">;

type ResolvedProps = typeof sharedDefaults &
  SectionProps & {
    avatarSrc: string;
    userEmail: string;
    userName: string;
  };

const Logo = ({ props }: { props: ResolvedProps }) => (
  <Link href={props.logoHref}>
    <Img
      alt={props.logoAlt}
      src={props.logoSrc}
      style={{ maxWidth: "100%", verticalAlign: "middle" }}
      width={55}
    />
  </Link>
);

const Avatar = ({
  avatar,
  props,
}: {
  avatar: HeaderWithUserDetailsAvatar;
  props: ResolvedProps;
}) =>
  avatar === "image" ? (
    <Img
      alt={props.avatarAlt}
      src={props.avatarSrc}
      style={{ borderRadius: "9999px", verticalAlign: "middle" }}
      width={32}
    />
  ) : (
    <Section>
      <Fragment>
        <Row>
          <Column
            style={{
              backgroundColor: props.avatarBackgroundColor,
              borderRadius: "9999px",
              height: "32px",
              textAlign: "center",
              width: "32px",
            }}
          >
            <span
              style={{
                color: props.headingColor,
                fontFamily,
                fontSize: "10px",
                fontWeight: 600,
                lineHeight: "32px",
              }}
            >
              {props.initials}
            </span>
          </Column>
        </Row>
      </Fragment>
    </Section>
  );

const Details = ({
  alignRight = false,
  avatar,
  props,
}: {
  alignRight?: boolean;
  avatar: HeaderWithUserDetailsAvatar;
  props: ResolvedProps;
}) => (
  <Section
    align={alignRight ? "right" : undefined}
    style={alignRight ? { marginLeft: "auto" } : undefined}
  >
    <Fragment>
      <Row>
        <Column>
          <Avatar avatar={avatar} props={props} />
        </Column>
        <Column style={{ width: "12px" }}>&zwj;</Column>
        <Column>
          <Text
            style={{
              color: props.textColor,
              fontFamily,
              fontSize: "12px",
              fontWeight: 500,
              lineHeight: "16px",
              margin: 0,
            }}
          >
            {props.userName}
          </Text>
          <Text
            style={{
              color: props.mutedTextColor,
              fontFamily,
              fontSize: "12px",
              lineHeight: "16px",
              margin: 0,
            }}
          >
            {props.userEmail}
          </Text>
        </Column>
      </Row>
    </Fragment>
  </Section>
);

export const HeaderWithUserDetailsSection = (props: SectionProps) => {
  const alignment = props.alignment ?? "left";
  const avatar = props.avatar ?? "initials";
  const imageOnRight = avatar === "image" && alignment === "right";
  let userEmail = "johnadams@gmail.com";
  if (avatar === "image") {
    userEmail = imageOnRight ? "joanne@example.com" : "ajohn@example.com";
  }
  const resolved = {
    ...sharedDefaults,
    avatarSrc: imageOnRight
      ? emailAsset("reviews/avatar.jpg")
      : emailAsset("reviews/avatar-2.jpg"),
    userEmail,
    userName: imageOnRight ? "Joanne Smith" : "John Adams",
    ...props,
  } as ResolvedProps;
  return (
    <Section
      style={{ backgroundColor: resolved.pageBackgroundColor }}
      width="100%"
    >
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column style={{ maxWidth: "100%", width: "600px" }}>
            <Section width="100%">
              <Fragment>
                <Row>
                  <Column
                    style={{
                      backgroundColor: resolved.backgroundColor,
                      padding: "24px",
                    }}
                  >
                    <Section width="100%">
                      <Fragment>
                        <Row>
                          {alignment === "left" ? (
                            <>
                              <Column style={{ width: "55px" }}>
                                <Logo props={resolved} />
                              </Column>
                              <Column>
                                <Details
                                  alignRight
                                  avatar={avatar}
                                  props={resolved}
                                />
                              </Column>
                            </>
                          ) : (
                            <>
                              <Column>
                                <Details avatar={avatar} props={resolved} />
                              </Column>
                              <Column
                                style={{
                                  textAlign: "right",
                                  width: "55px",
                                }}
                              >
                                <Logo props={resolved} />
                              </Column>
                            </>
                          )}
                        </Row>
                      </Fragment>
                    </Section>
                  </Column>
                </Row>
              </Fragment>
            </Section>
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  );
};

export const HeaderWithUserDetails = ({
  alignment = "left",
  avatar = "initials",
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  ...props
}: HeaderWithUserDetailsProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
    </EmailHead>
    <Preview>John Adams</Preview>
    <Tailwind config={createEmailTailwindConfig(theme)}>
      <Body
        style={{ backgroundColor: pageBackgroundColor, fontFamily }}
        className="m-0"
      >
        <HeaderWithUserDetailsSection
          {...props}
          alignment={alignment}
          avatar={avatar}
          pageBackgroundColor={pageBackgroundColor}
        />
      </Body>
    </Tailwind>
  </Html>
);

HeaderWithUserDetails.PreviewProps = {
  alignment: "left",
  avatar: "initials",
  theme: defaultTheme,
} satisfies HeaderWithUserDetailsProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
